import React from 'react';

import {
  buildRunnerBoxAriaLabel,
  formatRunnerStatusDisplay,
  getRunnerBoxStyle,
  truncateRunnerText,
} from './runnerBoxUi';

/***
 * MARK: RunnerBox
 * @description Compact per-runner box for the Now Playing bar (plan q2/q3):
 *   runner name, task first line, stage line, and a health indicator that is
 *   never colour-only — the status word renders as text beside the dot
 *   (WCAG 1.4.1) while the dot itself is aria-hidden. Lines truncate in CSS
 *   with the full value on `title`; the tooltip text is capped so a
 *   paragraph-long goal cannot build an unusable tooltip. A box WITH a task
 *   is a button that opens the task inspector; a box WITHOUT a task is a
 *   greyed-out `idle` panel (display-only, plan q5). Three short lines fit
 *   the 72px bar; the status word shares the name line so no fourth line is
 *   needed.
 * @example <RunnerBox entry={{ runnerId: 'bravo', runnerLabel: 'Bravo', task: { id: 't1' }, taskTitleFirstLine: 'Ship it', stageName: 'Plan', statusWord: 'running' }} onOpenTask={(task) => setSelectedTask(task)} />
 * @param {Object} props - Component props.
 * @param {Object} props.entry - Runner entry ({ runnerId, runnerLabel, task, taskTitleFirstLine, stageName, statusWord }).
 * @param {Function} [props.onOpenTask] - Called with the task when a task-carrying box is activated.
 * @returns {React.ReactElement} The box (button when it has a task, panel when idle).
 ***/
export function RunnerBox({ entry, onOpenTask }) {
  // A blank id renders as an empty name and an empty test id — fail closed
  // to 'unknown' instead so the box stays findable and labelled.
  const rawRunnerId = entry?.runnerId;
  const runnerId =
    typeof rawRunnerId === 'string'
      ? (rawRunnerId.trim() !== '' ? rawRunnerId.trim() : 'unknown')
      : (rawRunnerId ?? 'unknown');
  const runnerName =
    typeof entry?.runnerLabel === 'string' && entry.runnerLabel.trim() !== ''
      ? entry.runnerLabel.trim()
      : String(runnerId);
  const statusWord = entry?.statusWord || 'idle';
  const style = getRunnerBoxStyle(statusWord);
  const testId = `runner-box-${runnerId}`;
  const label = buildRunnerBoxAriaLabel({ ...entry, runnerLabel: runnerName });
  const taskTitle =
    typeof entry?.taskTitleFirstLine === 'string' && entry.taskTitleFirstLine !== ''
      ? entry.taskTitleFirstLine
      : 'Untitled Task';
  const stageLine = entry?.stageName ? `Stage: ${entry.stageName}` : '—';

  const frameClass =
    'flex min-w-[120px] max-w-[180px] flex-col justify-center gap-0.5 rounded border border-border-standard bg-surface-container px-2 py-1 text-left';

  // Idle variant (plan q5): greyed-out panel, no click target. role="group"
  // so the aria-label (runner + status) stays valid on a non-interactive
  // element; the word `idle` is visible text, never colour-only.
  if (!entry?.task) {
    return (
      <div
        role="group"
        aria-label={label}
        data-testid={testId}
        title={truncateRunnerText(runnerName)}
        className={`${frameClass} opacity-60`}
      >
        <span className="flex min-w-0 items-center gap-1">
          <span className={`h-2 w-2 shrink-0 rounded-full ${style.dotClass}`} aria-hidden="true" />
          <span className="truncate text-[11px] font-bold text-text-muted" title={truncateRunnerText(runnerName)}>
            {runnerName}
          </span>
        </span>
        <span className="truncate text-[11px] text-text-muted">idle</span>
      </div>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onOpenTask?.(entry.task)}
      aria-label={label}
      data-testid={testId}
      className={`${frameClass} cursor-pointer hover:bg-surface-container-high focus:outline-none focus:ring-1 focus:ring-primary`}
    >
      <span className="flex min-w-0 items-center gap-1">
        <span className={`h-2 w-2 shrink-0 rounded-full ${style.dotClass}`} aria-hidden="true" />
        <span
          className="min-w-0 flex-1 truncate text-[11px] font-bold text-on-surface"
          title={truncateRunnerText(runnerName)}
        >
          {runnerName}
        </span>
        <span className={`shrink-0 text-[10px] font-semibold uppercase tracking-wide ${style.statusClass}`}>
          {formatRunnerStatusDisplay(statusWord)}
        </span>
      </span>
      <span
        className="truncate text-[11px] text-on-surface"
        title={truncateRunnerText(taskTitle)}
      >
        {taskTitle}
      </span>
      <span
        className="truncate text-[10px] text-text-muted"
        title={entry?.stageName ? truncateRunnerText(stageLine) : undefined}
      >
        {stageLine}
      </span>
    </button>
  );
}

import { expect, test, vi } from 'vitest';
import { screen, fireEvent, within } from '@testing-library/react';
import React from 'react';
import '@testing-library/jest-dom';

import { renderWithKainBain } from '../../testUtils';
import { RunnerBox } from './RunnerBox';

/***
 * MARK: RunnerBox tests
 * @description The compact box: name/task/stage/status word, colour per
 * status, click opens the inspector, idle boxes are display-only panels,
 * long names truncate with the full value on title.
 ***/

const runningEntry = {
  runnerId: 'bravo',
  runnerLabel: 'Bravo',
  taskId: 't1',
  task: { id: 't1', goal: 'Ship it', title: 'Ship it' },
  taskTitleFirstLine: 'Ship it',
  stageName: 'Plan',
  statusWord: 'running',
};

function renderBox(entry = runningEntry, onOpenTask = () => {}) {
  return renderWithKainBain(<RunnerBox entry={entry} onOpenTask={onOpenTask} />, {});
}

test('renders runner name, task name, stage, and status word with health colour', () => {
  renderBox();
  const box = screen.getByTestId('runner-box-bravo');
  expect(box.tagName).toBe('BUTTON');
  expect(box).toHaveTextContent('Bravo');
  expect(box).toHaveTextContent('Ship it');
  expect(box).toHaveTextContent('Stage: Plan');
  // Colour is never the sole signal: the status word renders as text.
  expect(box).toHaveTextContent('RUNNING');
  expect(box.getAttribute('aria-label')).toBe('Runner Bravo, running, task Ship it, stage Plan');
});

test('failed status renders the error colour and word', () => {
  renderBox({ ...runningEntry, statusWord: 'failed' });
  const box = screen.getByTestId('runner-box-bravo');
  expect(box).toHaveTextContent('FAILED');
  expect(box.innerHTML).toContain('bg-error');
});

test('clicking a task box opens that task in the inspector', () => {
  const onOpenTask = vi.fn();
  renderBox(runningEntry, onOpenTask);
  fireEvent.click(screen.getByTestId('runner-box-bravo'));
  expect(onOpenTask).toHaveBeenCalledTimes(1);
  expect(onOpenTask).toHaveBeenCalledWith(runningEntry.task);
});

test('a box without a task is a greyed-out idle panel, not a button', () => {
  const onOpenTask = vi.fn();
  renderWithKainBain(
    <RunnerBox
      entry={{ runnerId: 'solo', runnerLabel: 'Solo', task: null, taskId: null, taskTitleFirstLine: null, stageName: null, statusWord: 'idle' }}
      onOpenTask={onOpenTask}
    />,
    {},
  );
  const box = screen.getByTestId('runner-box-solo');
  expect(box.tagName).toBe('DIV');
  expect(box).toHaveTextContent('Solo');
  expect(box).toHaveTextContent('idle');
  expect(box.className).toContain('opacity-60');
  // Display-only: no click handler fires.
  fireEvent.click(box);
  expect(onOpenTask).not.toHaveBeenCalled();
});

test('blank runner id and label fail closed to unknown instead of empty', () => {
  renderBox({ ...runningEntry, runnerId: '   ', runnerLabel: '   ' });
  const box = screen.getByTestId('runner-box-unknown');
  expect(box).toHaveTextContent('unknown');
  expect(box.getAttribute('aria-label')).toBe(
    'Runner unknown, running, task Ship it, stage Plan',
  );
});

test('missing stage renders an em dash and long names keep full titles', () => {
  const longName = `Runner with a very long name ${'x'.repeat(300)}`;
  const longTask = `Task with a very long title ${'y'.repeat(300)}`;
  renderBox({
    ...runningEntry,
    runnerLabel: longName,
    taskTitleFirstLine: longTask,
    stageName: null,
  });
  const box = screen.getByTestId('runner-box-bravo');
  expect(box).toHaveTextContent('—');
  expect(within(box).queryByText(/Stage:/)).not.toBeInTheDocument();
  // Truncated on screen (CSS) but the full value survives on title.
  const nameLine = screen.getByTitle(longName.slice(0, 239) + '…');
  expect(nameLine).toHaveTextContent(longName.slice(0, 20));
  expect(screen.getByTitle(longTask.slice(0, 239) + '…')).toBeInTheDocument();
});
